/** Types mirroring openapi.json (generated by the backend from its zod schemas). */

export type Role = 'admin' | 'supervisor' | 'agent'
export type UserStatus = 'active' | 'disabled'

export interface User {
  _id: string
  email: string
  name: string
  role: Role
  status: UserStatus
  lastLoginAt?: string
  createdAt: string
  updatedAt: string
}

export interface LoginResponse {
  token: string
  tokenType: 'Bearer'
  expiresAt: string
  user: User
}

export interface Inbox {
  _id: string
  name: string
  description?: string
  color: string
  memberIds: string[]
  isDefault: boolean
  createdAt: string
  updatedAt: string
}

export type ConversationStatus = 'open' | 'pending' | 'resolved'

export interface Conversation {
  _id: string
  contactId: string
  inboxId: string
  status: ConversationStatus
  active: boolean
  assigneeId: string | null
  labelIds: string[]
  lastMessageAt: string
  lastMessagePreview?: string
  lastInboundAt?: string
  unreadCount: number
  resolvedAt?: string
  createdAt: string
  updatedAt: string
}

export type MessageDirection = 'inbound' | 'outbound'
export type MessageStatus = 'received' | 'queued' | 'sent' | 'delivered' | 'read' | 'failed'

export interface MessageMedia {
  waMediaId: string
  mimeType?: string
  sha256?: string
  caption?: string
  filename?: string
  s3Key?: string
}

export interface Message {
  _id: string
  conversationId: string
  contactId: string
  direction: MessageDirection
  waMessageId?: string
  type: string
  text?: string
  media?: MessageMedia
  location?: { latitude: number; longitude: number; name?: string; address?: string }
  reply?: { id?: string; title?: string }
  reaction?: { messageId: string; emoji?: string }
  replyToWaMessageId?: string
  status: MessageStatus
  statusAt?: string
  error?: { code: number; title?: string; message?: string }
  sentBy?: string
  sentAt: string
  createdAt: string
  updatedAt: string
}

export interface Label {
  _id: string
  name: string
  nameKey: string
  color: string
  description?: string
  createdAt: string
  updatedAt: string
}

export interface Stage {
  _id: string
  name: string
  color: string
  probability: number
}

export interface Pipeline {
  _id: string
  name: string
  stages: Stage[]
  createdAt: string
  updatedAt: string
}

export interface BoardColumn extends Stage {
  dealCount: number
  totalValue: number
  weightedValue: number
}

export interface Board {
  pipeline: { _id: string; name: string }
  columns: BoardColumn[]
  totals: { dealCount: number; totalValue: number; weightedValue: number }
}

export type DealStatus = 'open' | 'won' | 'lost'

export interface Deal {
  _id: string
  title: string
  value: number
  currency: string
  pipelineId: string
  stageId: string
  contactId: string
  conversationId?: string
  ownerId?: string
  labelIds: string[]
  status: DealStatus
  lostReason?: string
  expectedCloseDate?: string
  closedAt?: string
  notes?: string
  createdBy: string
  createdAt: string
  updatedAt: string
}

export interface Page<T> {
  data: T[]
  nextCursor: string | null
}

export interface ApiErrorBody {
  error: { code: string; message: string; details: Record<string, unknown> }
}

/* Request bodies */

export interface CreateUserInput {
  email: string
  name: string
  password: string
  role?: Role
}
export interface UpdateUserInput {
  name?: string
  role?: Role
  status?: UserStatus
  password?: string
}

export interface CreateInboxInput {
  name: string
  description?: string
  color?: string
  memberIds?: string[]
}
export interface UpdateInboxInput {
  name?: string
  description?: string
  color?: string
  isDefault?: true
}

export interface ListConversationsQuery {
  inboxId?: string
  status?: ConversationStatus
  assignee?: 'me' | 'unassigned' | (string & {})
  labelId?: string
  limit?: number
  cursor?: string
}

export interface CreateLabelInput {
  name: string
  color?: string
  description?: string
}
export type UpdateLabelInput = Partial<CreateLabelInput>

export interface StageInput {
  name: string
  color?: string
  probability?: number
}
export interface CreatePipelineInput {
  name: string
  stages?: StageInput[]
}

export interface ListDealsQuery {
  pipelineId?: string
  stageId?: string
  status?: DealStatus
  ownerId?: string
  contactId?: string
  labelId?: string
  limit?: number
  cursor?: string
}
export interface CreateDealInput {
  title: string
  pipelineId: string
  contactId: string
  stageId?: string
  value?: number
  currency?: string
  conversationId?: string
  ownerId?: string
  expectedCloseDate?: string
  notes?: string
}
export interface UpdateDealInput {
  title?: string
  value?: number
  currency?: string
  ownerId?: string | null
  expectedCloseDate?: string | null
  notes?: string
}
export type DealStatusInput =
  | { status: 'open' }
  | { status: 'won' }
  | { status: 'lost'; lostReason?: string }
